THOUGHT: Now I can see how the `getModuleNameInline` function is used. It's called from `loadModuleInline`, which is used when loading modules with an inline key specification.

The issue I identified earlier is indeed present. When `getModuleNameInline` encounters an error (such as when the module name is missing or not a string), it includes the entire configuration object in the error message using `%+v`. This could expose sensitive information.

Let me create a simple test to demonstrate this issue:

```bash
cat <<'EOF' > test_module_name_inline.go
package main

import (
	"encoding/json"
	"fmt"
)

// Simulating the getModuleNameInline function
func getModuleNameInline(moduleNameKey string, raw json.RawMessage) (string, json.RawMessage, error) {
	var tmp map[string]any
	err := json.Unmarshal(raw, &tmp)
	if err != nil {
		return "", nil, err
	}

	moduleName, ok := tmp[moduleNameKey].(string)
	if !ok || moduleName == "" {
		// This is the problematic line - it exposes the entire config in the error message
		return "", nil, fmt.Errorf("module name not specified with key '%s' in %+v", moduleNameKey, tmp)
	}

	// Remove key from the object (simplified)
	delete(tmp, moduleNameKey)
	result, err := json.Marshal(tmp)
	if err != nil {
		return "", nil, fmt.Errorf("re-encoding module configuration: %v", err)
	}

	return moduleName, result, nil
}

func main() {
	// Example with sensitive data
	config := `{"handler": "file_server", "secret_token": "SECRET123", "password": "mypassword"}`

	moduleName, _, err := getModuleNameInline("handler", json.RawMessage(config))
	if err != nil {
		fmt.Printf("Error: %v\n", err)
	} else {
		fmt.Printf("Module name: %s\n", moduleName)
	}

	// Example with missing module name
	badConfig := `{"secret_token": "SECRET123", "password": "mypassword"}`

	_, _, err = getModuleNameInline("handler", json.RawMessage(badConfig))
	if err != nil {
		fmt.Printf("Error: %v\n", err)
	}
}
EOF
```

